  // ---- getting started
  'topic.start.title': 'Getting started',
  'topic.start.desc': 'Sign in, find your way around the portal, set language and theme.',
  'topic.start.intro': 'HvPortal manages Hyper-V hosts and their virtual machines from the browser. Every user sees only the hosts, groups and VMs that their roles allow, and only the actions they may perform on them.',
  'topic.start.signin': 'Sign in',
  'topic.start.s1.title': 'Open the portal and sign in',
  'topic.start.s1.help': 'Open the address given by your administrator. With a local account enter user name and password. If your organization uses Microsoft Entra ID choose "Sign in with Microsoft": your account must have been created in the portal by an administrator first.',
